/**
 * NullBrokerAdapter — CompletionBrokerPort no-op adapter.
 *
 * Wave 2: the broker port exists for type safety but the in-memory
 * implementation (InMemoryBrokerAdapter) ships in Wave 3 (T3).
 * Until then this no-op satisfies the interface without changing flow —
 * the blocking spawn-and-await pattern in SubProcessAdapterW2 makes the
 * broker unnecessary in this wave.
 */

import type {
  CompletionBrokerPort,
  ExecutorHandle,
  ExecutorCompletion,
} from "@workflow/runtime-abi";

export class NullBrokerAdapter implements CompletionBrokerPort {
  async register(
    _handle: ExecutorHandle,
    _nonce: string,
    _metadata: import("@workflow/runtime-abi").HandleMetadata,
  ): Promise<void> {
    // no-op in Wave 2
  }

  async listCompleted(_opts?: {
    max?: number;
    lockMs?: number;
  }): Promise<ExecutorCompletion[]> {
    return [];
  }

  async ack(_handle: ExecutorHandle): Promise<void> {
    // no-op in Wave 2
  }

  async nack(_handle: ExecutorHandle): Promise<void> {
    // no-op in Wave 2
  }
}

