/**
 * local-subprocess profile factory.
 *
 * Bundles the Wave-2 adapter set into a RuntimePorts instance for the
 * single-container, single-process topology: orchestrator and executor
 * run as child processes inside the same image.
 *
 * Adapter set:
 *   ExecutorPort         → SubProcessAdapterW2  (blocks in Wave 2; async in Wave 3)
 *   CompletionBrokerPort → NullBrokerAdapter     (no-op until Wave 3 / T3)
 *   BriefingTransport    → LocalFileBriefingAdapter
 *   WorkflowState        → GitWorkflowStateAdapter
 *   Credential           → EnvCredentialAdapter
 *   WorkspacePull        → GitClonePullAdapter
 *   EventEmitter         → StdoutJsonEmitter
 *   Scheduler            → SimpleSleepScheduler
 *   Clock                → RealClock
 */

import type { RuntimePorts } from "../runtime-ports.js";
import { SubProcessAdapterW2, type SubProcessAdapterOpts } from "../adapters/executor/subprocess.js";
import { NullBrokerAdapter } from "../adapters/broker/null.js";
import { LocalFileBriefingAdapter } from "../adapters/briefing/local-file.js";
import { GitWorkflowStateAdapter } from "../adapters/workflow-state/git.js";
import { EnvCredentialAdapter } from "../adapters/credential/env.js";
import { GitClonePullAdapter } from "../adapters/workspace-pull/git-clone-pull.js";
import { StdoutJsonEmitter } from "../adapters/emitter/stdout-json.js";
import { SimpleSleepScheduler } from "../adapters/scheduler/simple-sleep.js";
import { RealClock } from "../adapters/clock/real.js";

export interface LocalSubprocessProfileOpts {
  /** Options forwarded to SubProcessAdapterW2. */
  executor?: SubProcessAdapterOpts;
  /** Git identity for WorkflowStatePort operations. */
  gitAuthorEmail: string;
  gitAuthorName?: string;
  sshKeyPath?: string;
}

/**
 * Create a RuntimePorts bundle wired for the local-subprocess profile.
 *
 * Called once at orchestrator startup; the returned bundle is passed to
 * every concern that needs port access.
 */
export function createLocalSubprocessProfile(
  opts: LocalSubprocessProfileOpts,
): RuntimePorts {
  return {
    executor: new SubProcessAdapterW2(opts.executor),
    broker: new NullBrokerAdapter(),
    briefing: new LocalFileBriefingAdapter(),
    workflowState: new GitWorkflowStateAdapter({
      gitAuthorEmail: opts.gitAuthorEmail,
      gitAuthorName: opts.gitAuthorName,
      sshKeyPath: opts.sshKeyPath,
    }),
    credential: new EnvCredentialAdapter(),
    workspacePull: new GitClonePullAdapter(),
    emitter: new StdoutJsonEmitter(),
    scheduler: new SimpleSleepScheduler(),
    clock: new RealClock(),
  };
}

/**
 * RuntimePorts — the full set of port interfaces the orchestrator core depends on.
 *
 * A profile factory creates one RuntimePorts bundle at startup; the bundle is
 * then injected into the orchestrator concerns. The core never touches concrete
 * adapter classes — only this interface bundle.
 */

import type {
  ExecutorPort,
  CompletionBrokerPort,
  BriefingTransportPort,
  WorkflowStatePort,
  CredentialPort,
  WorkspacePullPort,
  EventEmitterPort,
  SchedulerPort,
  ClockPort,
} from "@workflow/runtime-abi";

export interface RuntimePorts {
  /** Spawn an executor; return a handle immediately (async in Wave 3+). */
  executor: ExecutorPort;

  /** Completion queue — in-flight registry + peek-and-lock drain. */
  broker: CompletionBrokerPort;

  /** Deliver briefings to executors. */
  briefing: BriefingTransportPort;

  /** Read/write workflow state (task YAMLs, logs). */
  workflowState: WorkflowStatePort;

  /** Provide credentials (GitHub token, SSH key path) to executors. */
  credential: CredentialPort;

  /** Materialize workspace repos (clone + pull). */
  workspacePull: WorkspacePullPort;

  /** Emit structured events / metrics. */
  emitter: EventEmitterPort;

  /** Control cycle cadence (sleep between cycles). */
  scheduler: SchedulerPort;

  /** Wall-clock time and sleep (mockable in tests). */
  clock: ClockPort;
}

