/**
 * SubProcessAdapterW2 — ExecutorPort adapter (Wave 2).
 *
 * Wave 2 version preserves today's blocking flow: submit() spawns the executor
 * and awaits its exit before returning the handle. The result is stored in a
 * local map; readResult() retrieves and removes it.
 *
 * This matches today's behaviour exactly — the orchestrator still doesn't
 * advance its loop until the executor exits. The non-blocking async pattern
 * ships in Wave 3 (T5) when the CompletionBrokerPort is fully wired.
 *
 * The existing SubProcessAdapter in adapter/spawn.ts (ExecutorAdapter) is
 * preserved unchanged for backward compatibility with existing seam tests.
 */

import { randomUUID } from "node:crypto";
import type {
  ExecutorPort,
  ExecutorPortInput,
  ExecutorHandle,
  ExecutorResult,
} from "@workflow/runtime-abi";
import {
  SubProcessAdapter,
  type SubProcessAdapterOpts,
} from "../../adapter/spawn.js";

export { type SubProcessAdapterOpts };

export class SubProcessAdapterW2 implements ExecutorPort {
  private readonly legacy: SubProcessAdapter;
  private readonly results = new Map<ExecutorHandle, ExecutorResult>();

  constructor(opts: SubProcessAdapterOpts = {}) {
    this.legacy = new SubProcessAdapter(opts);
  }

  async submit(input: ExecutorPortInput): Promise<ExecutorHandle> {
    const handle = randomUUID();
    // Wave 2: still blocks until the executor exits (preserves today's flow).
    // Wave 3 (T5) refactors this to async submit + broker callback.
    const result = await this.legacy.run(input);
    this.results.set(handle, result);
    return handle;
  }

  async readResult(handle: ExecutorHandle): Promise<ExecutorResult> {
    const result = this.results.get(handle);
    if (!result) {
      return { terminal_status: "failed", blocked_reason: "handle_not_found" };
    }
    this.results.delete(handle);
    return result;
  }
}

