1	import { describe, it, expect, beforeEach } from "vitest";
2	import { FakeBrokerAdapter } from "../src/fake-broker.js";
3	import { createFakeClock } from "../src/fake-ports.js";
4	import type { HandleMetadata, RunnerCallbackPayload } from "../src/types.js";
5	
6	function meta(taskId = "T1"): HandleMetadata {
7	  return {
8	    kind: "impl",
9	    task_id: taskId,
10	    feature_id: "test-feature",
11	    started_at: new Date(0).toISOString(),
12	  };
13	}
14	
15	describe("FakeBrokerAdapter", () => {
16	  let broker: FakeBrokerAdapter;
17	
18	  beforeEach(() => {
19	    broker = new FakeBrokerAdapter();
20	  });
21	
22	  // ── register ─────────────────────────────────────────────────────────────
23	
24	  it("registers a handle and increments registrySize", async () => {
25	    await broker.register("h1", "nonce-1", meta());
26	    expect(broker.registrySize()).toBe(1);
27	  });
28	
29	  it("throws when registering a duplicate handle", async () => {
30	    await broker.register("h1", "nonce-1", meta());
31	    await expect(broker.register("h1", "nonce-1", meta())).rejects.toThrow(
32	      /already registered/,
33	    );
34	  });
35	
36	  // ── postCallback ──────────────────────────────────────────────────────────
37	
38	  it("enqueues a completion after a valid postCallback", async () => {
39	    await broker.register("h1", "nonce-1", meta());
40	    broker.postCallback({ handle: "h1", nonce: "nonce-1", result: { terminal_status: "in_review" } });
41	    expect(broker.queueDepth()).toBe(1);
42	  });
43	
44	  it("throws postCallback for an unknown handle", async () => {
45	    expect(() =>
46	      broker.postCallback({ handle: "unknown", nonce: "x", result: { terminal_status: "in_review" } }),
47	    ).toThrow(/unknown handle/);
48	  });
49	
50	  it("throws postCallback for a nonce mismatch", async () => {
51	    await broker.register("h1", "correct-nonce", meta());
52	    expect(() =>
53	      broker.postCallback({ handle: "h1", nonce: "wrong-nonce", result: { terminal_status: "in_review" } }),
54	    ).toThrow(/nonce mismatch/);
55	  });
56	
57	  // ── listCompleted ─────────────────────────────────────────────────────────
58	
59	  it("returns unlocked completions", async () => {
60	    await broker.register("h1", "n1", meta("T1"));
61	    await broker.register("h2", "n2", meta("T2"));
62	    broker.postCallback({ handle: "h1", nonce: "n1", result: { terminal_status: "in_review" } });
63	    broker.postCallback({ handle: "h2", nonce: "n2", result: { terminal_status: "blocked", blocked_reason: "test" } });
64	
65	    const completions = await broker.listCompleted();
66	    expect(completions).toHaveLength(2);
67	    expect(completions[0].handle).toBe("h1");
68	    expect(completions[1].handle).toBe("h2");
69	  });
70	
71	  it("respects the max option", async () => {
72	    for (let i = 0; i < 5; i++) {
73	      await broker.register(`h${i}`, `n${i}`, meta(`T${i}`));
74	      broker.postCallback({ handle: `h${i}`, nonce: `n${i}`, result: { terminal_status: "in_review" } });
75	    }
76	    const completions = await broker.listCompleted({ max: 2 });
77	    expect(completions).toHaveLength(2);
78	  });
79	
80	  it("does not return already-locked completions", async () => {
81	    await broker.register("h1", "n1", meta());
82	    broker.postCallback({ handle: "h1", nonce: "n1", result: { terminal_status: "in_review" } });
83	
84	    const first = await broker.listCompleted({ lockMs: 5000 });
85	    expect(first).toHaveLength(1);
86	    expect(broker.lockedCount()).toBe(1);
87	
88	    const second = await broker.listCompleted({ lockMs: 5000 });
89	    expect(second).toHaveLength(0);
90	  });
91	
92	  it("sets locked_until on returned completions", async () => {
93	    const clock = createFakeClock(1000);
94	    broker = new FakeBrokerAdapter(clock);
95	
96	    await broker.register("h1", "n1", meta());
97	    broker.postCallback({ handle: "h1", nonce: "n1", result: { terminal_status: "in_review" } });
98	
99	    const [completion] = await broker.listCompleted({ lockMs: 5000 });
100	    expect(completion.locked_until).toBe(6000); // 1000 + 5000
101	  });
102	
103	  it("includes handle metadata in completions", async () => {
104	    const m = { kind: "review-fix" as const, subkind: "rebase" as const, task_id: "T5", feature_id: "feat", started_at: "2026-01-01T00:00:00.000Z" };
105	    await broker.register("h1", "n1", m);
106	    broker.postCallback({ handle: "h1", nonce: "n1", result: { terminal_status: "in_review" } });
107	
108	    const [completion] = await broker.listCompleted();
109	    expect(completion.metadata.kind).toBe("review-fix");
110	    expect(completion.metadata.subkind).toBe("rebase");
111	    expect(completion.metadata.task_id).toBe("T5");
112	  });
113	
114	  // ── ack ───────────────────────────────────────────────────────────────────
115	
116	  it("removes the handle from registry and queue on ack", async () => {
117	    await broker.register("h1", "n1", meta());
118	    broker.postCallback({ handle: "h1", nonce: "n1", result: { terminal_status: "in_review" } });
119	
120	    await broker.listCompleted(); // lock it
121	    await broker.ack("h1");
122	
123	    expect(broker.registrySize()).toBe(0);
124	    expect(broker.queueDepth()).toBe(0);
125	  });
126	
127	  it("ack is a no-op for an unknown handle (idempotent)", async () => {
128	    await expect(broker.ack("unknown")).resolves.toBeUndefined();
129	  });
130	
