import { describe, it, expect, beforeEach } from "vitest";
import { FakeBrokerAdapter } from "../src/fake-broker.js";
import { createFakeClock } from "../src/fake-ports.js";
import type { HandleMetadata, RunnerCallbackPayload } from "../src/types.js";

function meta(taskId = "T1"): HandleMetadata {
  return {
    kind: "impl",
    task_id: taskId,
    feature_id: "test-feature",
    started_at: new Date(0).toISOString(),
  };
}

describe("FakeBrokerAdapter", () => {
  let broker: FakeBrokerAdapter;

  beforeEach(() => {
    broker = new FakeBrokerAdapter();
  });

  // ── register ─────────────────────────────────────────────────────────────

  it("registers a handle and increments registrySize", async () => {
    await broker.register("h1", "nonce-1", meta());
    expect(broker.registrySize()).toBe(1);
  });

  it("throws when registering a duplicate handle", async () => {
    await broker.register("h1", "nonce-1", meta());
    await expect(broker.register("h1", "nonce-1", meta())).rejects.toThrow(
      /already registered/,
    );
  });

  // ── postCallback ──────────────────────────────────────────────────────────

  it("enqueues a completion after a valid postCallback", async () => {
    await broker.register("h1", "nonce-1", meta());
    broker.postCallback({ handle: "h1", nonce: "nonce-1", result: { terminal_status: "in_review" } });
    expect(broker.queueDepth()).toBe(1);
  });

  it("throws postCallback for an unknown handle", async () => {
    expect(() =>
      broker.postCallback({ handle: "unknown", nonce: "x", result: { terminal_status: "in_review" } }),
    ).toThrow(/unknown handle/);
  });

  it("throws postCallback for a nonce mismatch", async () => {
    await broker.register("h1", "correct-nonce", meta());
    expect(() =>
      broker.postCallback({ handle: "h1", nonce: "wrong-nonce", result: { terminal_status: "in_review" } }),
    ).toThrow(/nonce mismatch/);
  });

  // ── listCompleted ─────────────────────────────────────────────────────────

  it("returns unlocked completions", async () => {
    await broker.register("h1", "n1", meta("T1"));
    await broker.register("h2", "n2", meta("T2"));
    broker.postCallback({ handle: "h1", nonce: "n1", result: { terminal_status: "in_review" } });
    broker.postCallback({ handle: "h2", nonce: "n2", result: { terminal_status: "blocked", blocked_reason: "test" } });

    const completions = await broker.listCompleted();
    expect(completions).toHaveLength(2);
    expect(completions[0].handle).toBe("h1");
    expect(completions[1].handle).toBe("h2");
  });

  it("respects the max option", async () => {
    for (let i = 0; i < 5; i++) {
      await broker.register(`h${i}`, `n${i}`, meta(`T${i}`));
      broker.postCallback({ handle: `h${i}`, nonce: `n${i}`, result: { terminal_status: "in_review" } });
    }
    const completions = await broker.listCompleted({ max: 2 });
    expect(completions).toHaveLength(2);
  });

  it("does not return already-locked completions", async () => {
    await broker.register("h1", "n1", meta());
    broker.postCallback({ handle: "h1", nonce: "n1", result: { terminal_status: "in_review" } });

    const first = await broker.listCompleted({ lockMs: 5000 });
    expect(first).toHaveLength(1);
    expect(broker.lockedCount()).toBe(1);

    const second = await broker.listCompleted({ lockMs: 5000 });
    expect(second).toHaveLength(0);
  });

  it("sets locked_until on returned completions", async () => {
    const clock = createFakeClock(1000);
    broker = new FakeBrokerAdapter(clock);

    await broker.register("h1", "n1", meta());
    broker.postCallback({ handle: "h1", nonce: "n1", result: { terminal_status: "in_review" } });

    const [completion] = await broker.listCompleted({ lockMs: 5000 });
    expect(completion.locked_until).toBe(6000); // 1000 + 5000
  });

  it("includes handle metadata in completions", async () => {
    const m = { kind: "review-fix" as const, subkind: "rebase" as const, task_id: "T5", feature_id: "feat", started_at: "2026-01-01T00:00:00.000Z" };
    await broker.register("h1", "n1", m);
    broker.postCallback({ handle: "h1", nonce: "n1", result: { terminal_status: "in_review" } });

    const [completion] = await broker.listCompleted();
    expect(completion.metadata.kind).toBe("review-fix");
    expect(completion.metadata.subkind).toBe("rebase");
    expect(completion.metadata.task_id).toBe("T5");
  });

  // ── ack ───────────────────────────────────────────────────────────────────

  it("removes the handle from registry and queue on ack", async () => {
    await broker.register("h1", "n1", meta());
    broker.postCallback({ handle: "h1", nonce: "n1", result: { terminal_status: "in_review" } });

    await broker.listCompleted(); // lock it
    await broker.ack("h1");

    expect(broker.registrySize()).toBe(0);
    expect(broker.queueDepth()).toBe(0);
  });

  it("ack is a no-op for an unknown handle (idempotent)", async () => {
    await expect(broker.ack("unknown")).resolves.toBeUndefined();
  });

  // ── nack ──────────────────────────────────────────────────────────────────

  it("nack unlocks a locked item, making it available again", async () => {
    await broker.register("h1", "n1", meta());
    broker.postCallback({ handle: "h1", nonce: "n1", result: { terminal_status: "in_review" } });

    await broker.listCompleted({ lockMs: 60_000 });
    expect(broker.lockedCount()).toBe(1);

    await broker.nack("h1");
    expect(broker.lockedCount()).toBe(0);

    const retried = await broker.listCompleted({ lockMs: 60_000 });
    expect(retried).toHaveLength(1);
  });

  // ── reclaimExpired ────────────────────────────────────────────────────────

  it("reclaimExpired returns expired locks to the queue", async () => {
    const clock = createFakeClock(0);
    broker = new FakeBrokerAdapter(clock);

    await broker.register("h1", "n1", meta());
    broker.postCallback({ handle: "h1", nonce: "n1", result: { terminal_status: "in_review" } });

    await broker.listCompleted({ lockMs: 1000 });
    expect(broker.lockedCount()).toBe(1);

    // Advance past the lock expiry
    clock.advance(2000);
    broker.reclaimExpired();
    expect(broker.lockedCount()).toBe(0);

    const retried = await broker.listCompleted({ lockMs: 1000 });
    expect(retried).toHaveLength(1);
  });

  it("reclaimExpired is called automatically inside listCompleted", async () => {
    const clock = createFakeClock(0);
    broker = new FakeBrokerAdapter(clock);

    await broker.register("h1", "n1", meta());
    broker.postCallback({ handle: "h1", nonce: "n1", result: { terminal_status: "in_review" } });

    await broker.listCompleted({ lockMs: 1000 });

    clock.advance(2000);
    // listCompleted triggers reclaimExpired internally
    const retried = await broker.listCompleted({ lockMs: 1000 });
    expect(retried).toHaveLength(1);
  });

  // ── replay safety ─────────────────────────────────────────────────────────

  it("does not enqueue a second postCallback after ack (replay rejected)", async () => {
    await broker.register("h1", "n1", meta());
    broker.postCallback({ handle: "h1", nonce: "n1", result: { terminal_status: "in_review" } });
    await broker.listCompleted();
    await broker.ack("h1");

    // After ack the registry entry is gone; a replay must throw
    expect(() =>
      broker.postCallback({ handle: "h1", nonce: "n1", result: { terminal_status: "in_review" } }),
    ).toThrow(/unknown handle/);
  });
});

