/**
 * StdoutJsonEmitter — EventEmitterPort adapter.
 *
 * Emits structured JSON events to stdout, one object per line.
 * This is the production adapter for local profiles.
 */

import type { EventEmitterPort } from "@workflow/runtime-abi";

export class StdoutJsonEmitter implements EventEmitterPort {
  emit(event: string, data?: Record<string, unknown>): void {
    console.log(
      JSON.stringify({ at: new Date().toISOString(), type: event, ...data }),
    );
  }
}

