import { describe, it, expect, beforeEach, afterEach } from "vitest";
import * as http from "node:http";
import * as path from "node:path";
import * as os from "node:os";
import * as fs from "node:fs";
import { InMemoryBrokerAdapter } from "../../src/adapters/broker/in-memory.js";
import type { HandleMetadata, RunnerCallbackPayload } from "@workflow/runtime-abi";

// ── Helpers ───────────────────────────────────────────────────────────────────

function meta(taskId = "T1"): HandleMetadata {
  return {
    kind: "impl",
    task_id: taskId,
    feature_id: "test-feature",
    started_at: new Date(0).toISOString(),
  };
}

function makeClock(startMs = 0): { now(): number; advance(ms: number): void } {
  let t = startMs;
  return {
    now: () => t,
    advance: (ms: number) => { t += ms; },
  };
}

/** POST the callback payload to the broker's HTTP receiver. */
async function postCallback(
  port: number,
  payload: RunnerCallbackPayload,
): Promise<{ status: number; body: unknown }> {
  return new Promise((resolve, reject) => {
    const body = JSON.stringify(payload);
    const req = http.request(
      {
        hostname: "127.0.0.1",
        port,
        path: "/callback",
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "Content-Length": Buffer.byteLength(body),
        },
      },
      (res) => {
        const chunks: Buffer[] = [];
        res.on("data", (c: Buffer) => chunks.push(c));
        res.on("end", () => {
          let parsed: unknown = {};
          try {
            parsed = JSON.parse(Buffer.concat(chunks).toString());
          } catch { /* empty body is fine */ }
          resolve({ status: res.statusCode ?? 0, body: parsed });
        });
      },
    );
    req.on("error", reject);
    req.end(body);
  });
}

// ── Tests ─────────────────────────────────────────────────────────────────────

describe("InMemoryBrokerAdapter — CompletionBrokerPort contract", () => {
  let broker: InMemoryBrokerAdapter;

  beforeEach(() => {
    broker = new InMemoryBrokerAdapter({ reclaimIntervalMs: 60_000 });
  });

  afterEach(async () => {
    await broker.stop();
  });

  // ── register ───────────────────────────────────────────────────────────────

  it("registers a handle and reflects in registrySize", async () => {
    await broker.register("h1", "n1", meta());
    expect(broker.registrySize()).toBe(1);
  });

  it("throws on duplicate handle registration", async () => {
    await broker.register("h1", "n1", meta());
    await expect(broker.register("h1", "n1", meta())).rejects.toThrow(/already registered/);
  });

  // ── listCompleted (no HTTP) ────────────────────────────────────────────────

  it("returns empty list when queue is empty", async () => {
    const results = await broker.listCompleted();
    expect(results).toHaveLength(0);
  });

  it("ack removes handle from registry and queue", async () => {
    await broker.register("h1", "n1", meta());
    await broker.ack("h1");
    expect(broker.registrySize()).toBe(0);
    expect(broker.queueDepth()).toBe(0);
  });

  it("ack is idempotent on unknown handle", async () => {
    await expect(broker.ack("nonexistent")).resolves.toBeUndefined();
  });

  it("nack is a no-op on unknown handle", async () => {
    await expect(broker.nack("nonexistent")).resolves.toBeUndefined();
  });

  // ── reclaim sweep ──────────────────────────────────────────────────────────

  it("reclaim sweep returns expired locks to the queue", async () => {
    const clock = makeClock(0);
    const b = new InMemoryBrokerAdapter({ reclaimIntervalMs: 60_000, clock });
    afterEach(() => b.stop());

    await b.register("h1", "n1", meta());
    // Manually push an already-locked item
    await b.register("h2", "n2", meta("T2"));

    // Verify queue is empty still
    expect(b.queueDepth()).toBe(0);
  });
});

describe("InMemoryBrokerAdapter — peek-and-lock semantics", () => {
  let broker: InMemoryBrokerAdapter;
  let clock: ReturnType<typeof makeClock>;

  beforeEach(async () => {
    clock = makeClock(1_000);
    broker = new InMemoryBrokerAdapter({ reclaimIntervalMs: 60_000, clock });
    await broker.start();
  });

  afterEach(async () => {
    await broker.stop();
  });

  async function registerAndPost(handle: string, nonce: string, taskId = "T1") {
    await broker.register(handle, nonce, meta(taskId));
    await postCallback(broker.getPort()!, { handle, nonce, result: { terminal_status: "in_review" } });
  }

  it("listCompleted returns enqueued completions and marks them locked", async () => {
    await registerAndPost("h1", "n1");
    const results = await broker.listCompleted({ lockMs: 5_000 });
    expect(results).toHaveLength(1);
    expect(results[0].handle).toBe("h1");
    expect(results[0].locked_until).toBe(6_000); // clock at 1000 + 5000
    expect(broker.lockedCount()).toBe(1);
  });

  it("locked items are not returned by a second listCompleted", async () => {
    await registerAndPost("h1", "n1");
    await broker.listCompleted({ lockMs: 5_000 });
    const second = await broker.listCompleted({ lockMs: 5_000 });
    expect(second).toHaveLength(0);
  });

  it("respects max option", async () => {
    for (let i = 0; i < 5; i++) {
      await registerAndPost(`h${i}`, `n${i}`, `T${i}`);
    }
    const results = await broker.listCompleted({ max: 2 });
    expect(results).toHaveLength(2);
  });

  it("nack unlocks a locked item for the next listCompleted", async () => {
    await registerAndPost("h1", "n1");
    await broker.listCompleted({ lockMs: 60_000 });
    expect(broker.lockedCount()).toBe(1);

    await broker.nack("h1");
    expect(broker.lockedCount()).toBe(0);

    const retried = await broker.listCompleted({ lockMs: 5_000 });
    expect(retried).toHaveLength(1);
  });

  it("ack removes item from queue after listCompleted", async () => {
    await registerAndPost("h1", "n1");
    await broker.listCompleted();
    await broker.ack("h1");
    expect(broker.queueDepth()).toBe(0);
    expect(broker.registrySize()).toBe(0);
  });

  it("visibility-timeout reclaim returns expired items to the queue", async () => {
    await registerAndPost("h1", "n1");
    await broker.listCompleted({ lockMs: 1_000 });
    expect(broker.lockedCount()).toBe(1);

    clock.advance(2_000); // past lock expiry
    // listCompleted triggers reclaim internally
    const retried = await broker.listCompleted({ lockMs: 1_000 });
    expect(retried).toHaveLength(1);
  });

  it("includes handle metadata in completions", async () => {
    const m: HandleMetadata = {
      kind: "review-fix",
      subkind: "rebase",
      task_id: "T5",
      feature_id: "runtime-portable-architecture",
      started_at: "2026-01-01T00:00:00.000Z",
    };
    await broker.register("h1", "n1", m);
    await postCallback(broker.getPort()!, { handle: "h1", nonce: "n1", result: { terminal_status: "in_review" } });

    const [completion] = await broker.listCompleted();
    expect(completion.metadata.kind).toBe("review-fix");
    expect(completion.metadata.subkind).toBe("rebase");
    expect(completion.metadata.task_id).toBe("T5");
  });
});

describe("InMemoryBrokerAdapter — HTTP receiver", () => {
  let broker: InMemoryBrokerAdapter;

  beforeEach(async () => {
    broker = new InMemoryBrokerAdapter({ reclaimIntervalMs: 60_000 });
    await broker.start();
  });

  afterEach(async () => {
    await broker.stop();
  });

  it("returns 204 for a valid callback", async () => {
    await broker.register("h1", "n1", meta());
    const res = await postCallback(broker.getPort()!, {
      handle: "h1",
      nonce: "n1",
      result: { terminal_status: "in_review" },
    });
    expect(res.status).toBe(204);
    expect(broker.queueDepth()).toBe(1);
  });

  it("returns 401 for an unknown handle", async () => {
    const res = await postCallback(broker.getPort()!, {
      handle: "unknown",
      nonce: "n",
      result: { terminal_status: "in_review" },
    });
    expect(res.status).toBe(401);
    expect((res.body as { error: string }).error).toBe("unknown_handle");
  });

  it("returns 401 for a nonce mismatch", async () => {
    await broker.register("h1", "correct-nonce", meta());
    const res = await postCallback(broker.getPort()!, {
      handle: "h1",
      nonce: "wrong-nonce",
      result: { terminal_status: "in_review" },
    });
    expect(res.status).toBe(401);
    expect((res.body as { error: string }).error).toBe("nonce_mismatch");
  });

  it("returns 401 for a replay after ack", async () => {
    await broker.register("h1", "n1", meta());
    await postCallback(broker.getPort()!, { handle: "h1", nonce: "n1", result: { terminal_status: "in_review" } });
    await broker.listCompleted();
