/**
 * Unit tests for Wave 2 adapters.
 *
 * Tests cover:
 *   1. StdoutJsonEmitter — emits JSON with type and at fields
 *   2. SimpleSleepScheduler — resolves after ms delay
 *   3. RealClock — now() returns a number, nowIso() returns ISO string
 *   4. EnvCredentialAdapter — reads from injected env
 *   5. LocalFileBriefingAdapter — writes and cleans up temp files
 *   6. NullBrokerAdapter — all methods resolve without throwing
 *   7. SubProcessAdapterW2 — submit() blocks, readResult() returns stored result
 *   8. local-subprocess profile factory — returns a valid RuntimePorts bundle
 */

import { describe, it, expect, vi, afterEach } from "vitest";
import {
  mkdtempSync,
  readFileSync,
  existsSync,
  rmSync,
} from "node:fs";
import { join } from "node:path";
import { tmpdir } from "node:os";

import { StdoutJsonEmitter } from "../src/adapters/emitter/stdout-json.js";
import { SimpleSleepScheduler } from "../src/adapters/scheduler/simple-sleep.js";
import { RealClock } from "../src/adapters/clock/real.js";
import { EnvCredentialAdapter } from "../src/adapters/credential/env.js";
import { LocalFileBriefingAdapter } from "../src/adapters/briefing/local-file.js";
import { NullBrokerAdapter } from "../src/adapters/broker/null.js";
import { SubProcessAdapterW2 } from "../src/adapters/executor/subprocess.js";
import { createLocalSubprocessProfile } from "../src/profiles/local-subprocess.js";

// ── 1. StdoutJsonEmitter ──────────────────────────────────────────────────────

describe("StdoutJsonEmitter", () => {
  it("emits a JSON line with type and at fields", () => {
    const lines: string[] = [];
    vi.spyOn(console, "log").mockImplementation((msg: string) => lines.push(msg));

    const emitter = new StdoutJsonEmitter();
    emitter.emit("test_event", { foo: "bar" });

    expect(lines).toHaveLength(1);
    const parsed = JSON.parse(lines[0]!);
    expect(parsed.type).toBe("test_event");
    expect(parsed.foo).toBe("bar");
    expect(typeof parsed.at).toBe("string");

    vi.restoreAllMocks();
  });

  it("emits without extra data", () => {
    const lines: string[] = [];
    vi.spyOn(console, "log").mockImplementation((msg: string) => lines.push(msg));

    const emitter = new StdoutJsonEmitter();
    emitter.emit("ping");

    const parsed = JSON.parse(lines[0]!);

