// ── 8. local-subprocess profile factory ──────────────────────────────────────

describe("createLocalSubprocessProfile", () => {
  it("returns a RuntimePorts bundle with all nine ports populated", () => {
    const profile = createLocalSubprocessProfile({
      gitAuthorEmail: "agent@test.com",
      gitAuthorName: "Agent",
